fn independent(database:&SqliteDatabase,offset:i64)->SqliteDatabase{
 use std::{io::Write,process::{Command,Stdio}};let bytes=export_sqlite_database(database,Default::default(),&mut |_|true).unwrap();let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const n=Number(process.argv.at(-1));const q=s=>'"'+s+'"';d.exec('PRAGMA foreign_keys=OFF');for(const{name}of d.query("SELECT name FROM sqlite_schema WHERE type='table'").all()){const parents=d.query('PRAGMA foreign_key_list('+q(name)+')').all().map(r=>r.from).filter(v=>v!=='id');d.exec('UPDATE '+q(name)+' SET '+['id=id+'+n,...parents.map(c=>q(c)+'='+q(c)+'+'+n)].join(','));}if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('original SQLite joins');await Bun.write(Bun.stdout,d.serialize());d.close();"#;let mut child=Command::new("bun").args(["-e",script,"--",&offset.to_string()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));import_sqlite_database(&output.stdout,Default::default(),&mut |_|true).unwrap()
}
#[test]
fn obj_original_receiving_complete_fields_exact_words_and_independent_signed_indexes(){
 let c=contract();let coordinate=dialect();for word in c["binary64Words"].as_array().unwrap(){let value=f64::from_bits(u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let mut source=fixture();source.schema=c["literal"].as_str().unwrap().into();source.mtllib=Some(String::new());source.vertices[0].x=value;source.vertices[0].y=value;source.vertices[0].z=value;source.vertices[0].w=Some(value);source.texcoords[0].u=value;source.texcoords[0].v=value;source.texcoords[0].w=Some(value);source.normals[0].x=value;source.normals[0].y=value;source.normals[0].z=value;source.faces[0].vertices=vec![ObjFaceVertex{vertex:u32::MAX,texcoord:Some(u32::MAX),normal:None}];source.faces[1].vertices.clear();let words:Vec<u64>=c["u64Words"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().parse().unwrap()).collect();source.groups[0].name=c["literal"].as_str().unwrap().into();source.groups[0].faces=words.clone();source.objects[0].name=String::new();source.objects[0].faces=words.clone();source.usemtl=words.iter().map(|&face_index_from|ObjUsemtlRange{face_index_from,material:c["literal"].as_str().unwrap().into()}).collect();source.smoothing_groups=words.iter().enumerate().map(|(index,&face_index_from)|ObjSmoothingRange{face_index_from,group:if index==0{Some(0)}else{None}}).collect();source.unknown_statements[0].line_index=u64::MAX;source.unknown_statements[0].raw=c["literal"].as_str().unwrap().into();let pointer=source.schema.as_ptr();let expected=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let(projected,b,r)=decode(grant(),0,0,|sql,owner|source.to_sqlite_database_receiving(sql,owner));let projected=projected.unwrap();assert_eq!(projected,expected);let(a,z)=close(projected);assert_eq!(b+a,r+z);
  for offset in [0,-1,-1000]{let database=independent(&expected,offset);let input_pointer=database.tables.as_ptr();let(restored,b,r)=encode(grant(),0,0,|sql,owner|ObjSnapshot::from_sqlite_database_receiving(&database,sql,owner));let restored=restored.unwrap();let(actual,p,q)=decode(grant(),0,0,|sql,owner|restored.to_sqlite_database_receiving(sql,owner));assert_eq!(actual.as_ref().unwrap(),&expected);let(a,z)=close(actual.unwrap());assert_eq!(p+a,q+z);for(direction,born,released)in [decode(grant(),0,0,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause)),encode(grant(),0,0,|sql,owner|source.validate_sqlite_snapshot_subset_encoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause))]{direction.unwrap();assert_eq!(born,released)}let(a,z)=close(restored);assert_eq!(b+a,r+z);assert_eq!(input_pointer,database.tables.as_ptr());}assert_eq!(pointer,source.schema.as_ptr());}
 for library in [None,Some(String::new())]{let mut source=super::empty();source.schema=c["literal"].as_str().unwrap().into();source.mtllib=library;let(db,b,r)=decode(grant(),0,0,|sql,owner|source.to_sqlite_database_receiving(sql,owner));let db=db.unwrap();assert_eq!(db.tables[10].rows.len(),1);let(restored,p,q)=encode(grant(),0,0,|sql,owner|ObjSnapshot::from_sqlite_database_receiving(&db,sql,owner));let restored=restored.unwrap();assert_eq!(restored,source);let(a,z)=close(db);assert_eq!(b+a,r+z);let(a,z)=close(restored);assert_eq!(p+a,q+z);}eprintln!("[DEBUG] OBJ all11fields/14tables exact7IEEEwords, fullu64 and unresolvedu32, all options/literal NUL+UTF8+CRLF/order, emptyfaces/collections and independent signed0negative SQL joins qualified");
}
#[test]
fn obj_original_receiving_malformed_complete_fields_and_original_grant_axes(){
 let source=fixture();let coordinate=dialect();let baseline=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();for table in 0..14{for change in 0..5{let mut database=baseline.clone();let rows=&mut database.tables[table].rows;match change{0=>{rows.pop();},1=>{rows.push(rows[0].clone());},2=>rows[0].values[0]=SqliteValue::Integer(999),3=>{rows[0].values.pop();},_=>{if table==0{rows[0].values[1]=SqliteValue::Null}else{rows[0].values[1]=SqliteValue::Integer(999)}}}if change!=0{let(result,b,r)=encode(grant(),0,0,|sql,owner|ObjSnapshot::from_sqlite_database_receiving(&database,sql,owner).map(|_|()));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);assert_eq!(b,r)}for(result,b,r)in [decode(grant(),0,0,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause)),encode(grant(),0,0,|sql,owner|source.validate_sqlite_snapshot_subset_encoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause))]{assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);assert_eq!(b,r)}}}
 for edit in contract()["fieldEdits"].as_array().unwrap(){let table=baseline.tables.iter().position(|table|table.name==edit["table"].as_str().unwrap()).unwrap();let column=edit["column"].as_u64().unwrap()as usize;let value=match edit["storage"].as_str().unwrap(){"null"=>SqliteValue::Null,"text"=>SqliteValue::Text(edit["value"].as_str().unwrap().into()),"real"=>SqliteValue::Real(edit["value"].as_f64().unwrap()),_=>SqliteValue::Integer(edit["value"].as_i64().unwrap())};let mut database=baseline.clone();database.tables[table].rows[0].values[column]=value;for(result,b,r)in [decode(grant(),0,0,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause)),encode(grant(),0,0,|sql,owner|source.validate_sqlite_snapshot_subset_encoding(&coordinate,&database,sql,owner).map(|_|()).map_err(|error|error.cause))]{assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);assert_eq!(b,r)}}
 for axis in 0..5{let mut policy=grant();match axis{0=>policy.maximum_items=0,1=>policy.maximum_copy_bytes=0,2=>policy.maximum_capacity_bytes=0,3=>policy.maximum_release_bytes=0,_=>policy.maximum_depth=0}let(result,b,r)=decode(policy,0,0,|sql,owner|source.to_sqlite_database_receiving(sql,owner));assert!(result.is_err());assert_eq!(b,r);let(result,b,r)=encode(policy,0,0,|sql,owner|ObjSnapshot::from_sqlite_database_receiving(&baseline,sql,owner));assert!(result.is_err());assert_eq!(b,r);}eprintln!("[DEBUG] OBJ every14table missing/duplicate/alias/width/parent-text refusal and all5original grant axes retain paid prefixes and exact original SQL/native receipts");
}
