#[test]
fn obj_original_receiving_actual_prior_receipts_and_exact_coordinate_policy(){
 let source=fixture();let database=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let coordinate=dialect();
 macro_rules! prior{($native:ident,$owner:ident,$recipient:path,$method:ident)=>{{let mut observer=|_|true;let mut recipient=<$recipient>::new();let mut native=semio_framework_value::$native::new(67108864,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut callback=|_|true;let mut sql=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits{max_allocation_bytes:67108864,..Default::default()});let remaining=sql.allocation_remaining_bytes();let mut owner=store::$owner::new(&mut native,grant());let(result,heap)=observe(||source.$method(&coordinate,&database,&mut sql,&mut owner));result.unwrap();let first=owner.progress();assert!(first.retained_capacity_bytes>0&&first.released_bytes>0);assert_eq!((heap.requested_bytes,heap.released_bytes),(first.retained_capacity_bytes,first.released_bytes));let(result,heap)=observe(||source.$method(&coordinate,&database,&mut sql,&mut owner));result.unwrap();let total=owner.progress();assert_eq!((total.retained_capacity_bytes-first.retained_capacity_bytes,total.released_bytes-first.released_bytes),(heap.requested_bytes,heap.released_bytes));assert!(total.copied_items>first.copied_items&&total.copied_bytes>first.copied_bytes);for axis in 0..3{let mut wrong=dialect();match axis{0=>wrong.artifact_kind="wrong".into(),1=>wrong.standard="wrong".into(),_=>wrong.subset="wrong".into()}let(result,heap)=observe(||source.$method(&wrong,&database,&mut sql,&mut owner));let error=result.unwrap_err();assert_eq!(error.cause.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.cause.message,"OBJ owned SQLite dialect differs");assert_eq!(error.cause.retained_progress(),owner.progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}drop(owner);assert!(!native.has_retirement_owner());assert_eq!(remaining-sql.allocation_remaining_bytes(),native.owned_bytes());eprintln!("[DEBUG] OBJ same-original {} first={first:?} total={total:?} exactSQLNative=true",stringify!($method));}};}
 prior!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeRetirementRecipient,validate_sqlite_snapshot_subset_decoding);
 prior!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,validate_sqlite_snapshot_subset_encoding);
}
